import { EndGameValidator } from '@game-studio/end-game-validator';

import { loggingModel } from '../models/logging';
import { IBaseServerResponse } from '../types';
import { environment } from './environment';
import { eventEmitter } from './event-emitter';

export const endGameValidator: EndGameValidator<IBaseServerResponse> = new EndGameValidator();

endGameValidator.setLogger(handleValidationError);

function handleValidationError(message: string): void {
    loggingModel.logException(message);
    eventEmitter.emit('GLOBAL_ON_VALIDATION_ERROR');

    if (environment !== 'live') {
        console.error('END GAME VALIDATION FAILED');
        console.error(message);
    }
}
